head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > topLayout]<br/>Calendar 컴포넌트의 Today 버튼과 취소 버튼을 Header 영역에 배치할지 설정합니다.",
    "validation" : [
        "footerDiv=false, renderType=component, cancelButtonShow=true, calendarValueType=yearMonthDate 인 경우에 정상 동작합니다.",
        "미설정(기본값 false) 시 Today 버튼과 취소 버튼을 Footer 영역(하단)에 배치합니다.",
        "true 설정 시 Today 버튼과 취소 버튼을 Header 영역(우측 상단)에 배치합니다.",
        "true 설정 시 취소 버튼은 cancelButtonShow=true 이고 cancelButtonHide=false 인 경우에만 헤더에 배치됩니다.",
        "false (기본값) 설정 시 Today 버튼과 취소 버튼을 Footer 영역(하단)에 배치합니다.",        
        "topLayout 속성은 버튼의 배치 위치만 변경합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // topLayout 동작 조건: footerDiv=false, renderType=component, cancelButtonShow=true, cancelButtonHide=false, calendarValueType=yearMonthDate 고정
    let properties = {
        topLayout : con_topLayout.getText(),
        footerDiv : "false",
        renderType : "component",
        cancelButtonShow : "true",
        cancelButtonHide : "false",
        calendarValueType : "yearMonthDate"
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// [공통] Today 버튼 위치 (Header / Footer)
// validation: 미설정/false → Footer / true → Header
scwin.getTodayButtonPlacement = function () {
    let r = target1.render;
    let headerEl = r.querySelector('.w2calendar_header, .w2calendar_picker_header');
    let footerEl = null;
    let candidates = r.querySelectorAll('[class*="w2calendar_footer"]');
    for (let i = 0; i < candidates.length; i++) {
        let cn = candidates[i].className;
        if (cn.indexOf('w2calendar_footer_date') === -1
            && cn.indexOf('w2calendar_footer_hour') === -1
            && cn.indexOf('w2calendar_footer_min') === -1
            && cn.indexOf('w2calendar_footer_sec') === -1) {
            footerEl = candidates[i];
            break;
        }
    }

    let todayInHeader = headerEl ? headerEl.querySelector('[class*="w2calendar_go_today"]') : null;
    let todayInFooter = footerEl ? footerEl.querySelector('[class*="w2calendar_go_today"]') : null;

    let placement;
    if (todayInHeader && !todayInFooter) placement = 'Header';
    else if (!todayInHeader && todayInFooter) placement = 'Footer';
    else if (todayInHeader && todayInFooter) placement = 'Header+Footer';
    else placement = '없음';

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[Today 버튼 위치] " + placement
        + " (topLayout=" + target1.options.topLayout + ")"
    );
}



// [공통] 취소 버튼 위치 (Header / Footer)
// validation: true 설정 시 취소 버튼은 cancelButtonShow=true 이고 cancelButtonHide=false 인 경우에만 헤더에 배치됨
scwin.getCancelButtonPlacement = function () {
    let r = target1.render;
    let headerEl = r.querySelector('.w2calendar_header, .w2calendar_picker_header');
    let footerEl = null;
    let candidates = r.querySelectorAll('[class*="w2calendar_footer"]');
    for (let i = 0; i < candidates.length; i++) {
        let cn = candidates[i].className;
        if (cn.indexOf('w2calendar_footer_date') === -1
            && cn.indexOf('w2calendar_footer_hour') === -1
            && cn.indexOf('w2calendar_footer_min') === -1
            && cn.indexOf('w2calendar_footer_sec') === -1) {
            footerEl = candidates[i];
            break;
        }
    }

    let cancelInHeader = headerEl ? headerEl.querySelector('[class*="w2calendar_date_cancel"]') : null;
    let cancelInFooter = footerEl ? footerEl.querySelector('[class*="w2calendar_date_cancel"]') : null;

    let placement;
    if (cancelInHeader && !cancelInFooter) placement = 'Header';
    else if (!cancelInHeader && cancelInFooter) placement = 'Footer';
    else if (cancelInHeader && cancelInFooter) placement = 'Header+Footer';
    else placement = '없음 (미표시)';

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[취소 버튼 위치] " + placement
        + " (topLayout=" + target1.options.topLayout
        + ", cancelButtonShow=" + target1.options.cancleButtonShow
        + ", cancelButtonHide=" + target1.options.cancelButtonHide + ")"
    );
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getTodayButtonPlacement();
    scwin.getCancelButtonPlacement();
}
